// only returns the one matching row, with the requested edges: a
// `NotFoundError` when there is none, a `NotSingularError` when there are more.
pub fn (q PostQuery) only() !PostNode {
	nodes := q.limit(2).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'posts'
		}
	}
	if nodes.len > 1 {
		return NotSingularError{
			table: 'posts'
		}
	}
	return nodes[0]
}

// ids returns the keys of the matching rows, in order, and no edges.
pub fn (q PostQuery) ids() ![]i64 {
	keys := load.select_keys_where(q.graph.client.conn, 'posts', 'id', .i64, q.graph.client.prepare_query('posts', q.query)!, true)!
	return keys.map(it.i64())
}

// first_id returns the key of the first matching row, or a `NotFoundError`.
pub fn (q PostQuery) first_id() !i64 {
	ids := q.limit(1).ids()!
	if ids.len == 0 {
		return NotFoundError{
			table: 'posts'
		}
	}
	return ids[0]
}

// only_id returns the key of the one matching row: a `NotFoundError` when
// there is none, a `NotSingularError` when there are more.
pub fn (q PostQuery) only_id() !i64 {
	ids := q.limit(2).ids()!
	if ids.len == 0 {
		return NotFoundError{
			table: 'posts'
		}
	}
	if ids.len > 1 {
		return NotSingularError{
			table: 'posts'
		}
	}
	return ids[0]
}

// exist reports whether any row matches.
pub fn (q PostQuery) exist() !bool {
	return q.limit(1).ids()!.len > 0
}

// select reads only `columns`, and the key, of the rows; the others keep their
// zero values. An edge load needs the columns it follows.
pub fn (q PostQuery) select(columns ...string) PostQuery {
	mut all := columns.clone()
	if 'id' !in all {
		all << 'id'
	}
	mut next := q
	next.query = load.Query{
		...q.query
		columns: all
	}
	return next
}

// unique makes `scan` read each distinct row once.
pub fn (q PostQuery) unique() PostQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		distinct: true
	}
	return next
}

// scan reads the matching rows into `T`, the app's struct for some of the
// columns, by column name.
pub fn (q PostQuery) scan[T]() ![]T {
	return load.select_into[T](q.graph.client.conn, 'posts', 'id', .i64, q.graph.client.prepare_query('posts', q.query)!)
}

// order_by orders the rows by `orders` too, after the orders given before,
// such as `vgraph.desc('id').nulls_last()`.
pub fn (q PostQuery) order_by(orders ...load.Order) PostQuery {
	mut all := q.query.orders.clone()
	all << orders
	mut next := q
	next.query = load.Query{
		...q.query
		orders: all
	}
	return next
}

// for_update locks the matching rows (FOR UPDATE) until the transaction ends.
// It runs in `tx`, on PostgreSQL.
pub fn (q PostQuery) for_update() PostQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			mode: .update
		}
	}
	return next
}

// for_share locks the matching rows (FOR SHARE) until the transaction ends.
// It runs in `tx`, on PostgreSQL.
pub fn (q PostQuery) for_share() PostQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			mode: .share
		}
	}
	return next
}

// no_wait makes the lock one that fails at once on a row another transaction locked.
pub fn (q PostQuery) no_wait() PostQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			no_wait: true
		}
	}
	return next
}

// skip_locked makes the lock one that leaves out the rows other transactions locked.
pub fn (q PostQuery) skip_locked() PostQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			skip_locked: true
		}
	}
	return next
}

